from dowhy.causal_estimator import CausalEstimate
from dowhy.causal_refuters.dummy_outcome_refuter import refute_dummy_outcome, preprocess_data_by_treatment

class NewEst:
    def __init__(self, mode='mean'): self.mode=mode
    def fit(self, data, effect_modifier_names=None, **kwargs): self.data=data.copy(); return self
    def estimate_effect(self, data, control_value, treatment_value, target_units):
