        backdoor_variables={"backdoor": ["w"]},
        default_backdoor_id="backdoor",
        identifier_method="backdoor",
    )


def _mean_dummy_outcome(data):
    return float(data["dummy_outcome"].mean())


def _mean_dummy_outcome_requiring_unobserved_column(data):
    assert "simulated" in data.columns
    return float(data["dummy_outcome"].mean())


def _constant_effect_seven(data):
    return 7.0


class _FakeNewEstimator:
    """Minimal estimator object that records the dummy data it is fitted on."""

    def __init__(self, effect_function):
        self.effect_function = effect_function
        self.fitted_data = None

    def fit(self, data, effect_modifier_names=None, **kwargs):
        self.fitted_data = data.copy()
        return self

    def estimate_effect(self, data, control_value, treatment_value, target_units):
        return SimpleNamespace(value=self.effect_function(self.fitted_data))


class _FakeEstimator:
    """Boundary collaborator that creates a deterministic estimator on demand."""

    _effect_modifier_names = []
    _target_units = "ate"

    def __init__(self, effect_function=_mean_dummy_outcome):
        self.effect_function = effect_function
        self.received_estimand = None

    def get_new_estimator_object(self, identified_estimand):
        self.received_estimand = identified_estimand
        return _FakeNewEstimator(self.effect_function)


def _make_estimate(effect_function=_mean_dummy_outcome, estimand=None):
    estimand = estimand or _make_estimand()
    estimate = CausalEstimate(
        data=None,
        treatment_name=["t"],
        outcome_name=["y"],
        estimate=1.0,
        target_estimand=estimand,
        realized_estimand_expr=None,
        control_value=0,
        treatment_value=1,
    )
    estimate.add_estimator(_FakeEstimator(effect_function))
    return estimate


